ddl:
CREATE TABLE organizations (
    org_id VARCHAR(36) PRIMARY KEY,
    org_name VARCHAR(255) NOT NULL,
    plan_tier VARCHAR(50) NOT NULL,
    is_active BOOLEAN NOT NULL
);

CREATE TABLE user_events (
    event_id VARCHAR(36) PRIMARY KEY,
    org_id VARCHAR(36) REFERENCES organizations(org_id),
    event_type VARCHAR(100) NOT NULL,
    event_timestamp TIMESTAMP NOT NULL
);

CREATE TABLE assets (
    asset_id VARCHAR(36) PRIMARY KEY,
    ticker VARCHAR(10) UNIQUE NOT NULL,
    asset_type VARCHAR(50) NOT NULL
);

CREATE TABLE portfolios (
    portfolio_id VARCHAR(36) PRIMARY KEY,
    owner_id VARCHAR(36) NOT NULL,
    risk_profile VARCHAR(50) NOT NULL
);

CREATE TABLE transactions (
    tx_id VARCHAR(36) PRIMARY KEY,
    portfolio_id VARCHAR(36) REFERENCES portfolios(portfolio_id),
    asset_id VARCHAR(36) REFERENCES assets(asset_id),
    tx_type VARCHAR(10) NOT NULL,
    quantity NUMERIC(14, 4) NOT NULL,
    execution_price NUMERIC(12, 2) NOT NULL,
    tx_timestamp TIMESTAMP NOT NULL
);

CREATE TABLE patients (
    patient_id VARCHAR(36) PRIMARY KEY,
    birth_date DATE NOT NULL,
    gender VARCHAR(20) NOT NULL,
    blood_type VARCHAR(5) NOT NULL
);

CREATE TABLE appointments (
    appointment_id VARCHAR(36) PRIMARY KEY,
    patient_id VARCHAR(36) REFERENCES patients(patient_id),
    department VARCHAR(100) NOT NULL,
    appointment_date DATE NOT NULL,
    status VARCHAR(50) NOT NULL
);

CREATE TABLE diagnoses (
    diagnosis_id VARCHAR(36) PRIMARY KEY,
    appointment_id VARCHAR(36) REFERENCES appointments(appointment_id),
    icd_code VARCHAR(20) NOT NULL,
    severity VARCHAR(50) NOT NULL
);
